def transform(grid):
    # Compare the two upper patterned figures after aligning their colored
    # cores at the top-left; encode the differing cells.
    h, w = len(grid), len(grid[0])
    comps = []
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    q = (y+dy, x+dx)
                    if 0 <= q[0] < h and 0 <= q[1] < w and q not in seen and grid[q[0]][q[1]]:
                        seen.add(q)
                        stack.append(q)
            if len(cells) >= 8:
                comps.append(cells)
    comps.sort(key=len, reverse=True)
    if len(comps) < 2:
        return [[0]]
    def mask(cells):
        r0=min(r for r,c in cells); c0=min(c for r,c in cells)
        r1=max(r for r,c in cells); c1=max(c for r,c in cells)
        return {(r-r0,c-c0): grid[r][c] for r,c in cells}, r1-r0+1, c1-c0+1
    a, ah, aw = mask(comps[0])
    b, bh, bw = mask(comps[1])
    oh, ow = max(ah,bh), max(aw,bw)
    out = [[0]*ow for _ in range(oh)]
    for r in range(oh):
        for c in range(ow):
            if a.get((r,c),0) != b.get((r,c),0):
                out[r][c] = 8
    while len(out)>1 and not any(out[0]): out.pop(0)
    while len(out)>1 and not any(out[-1]): out.pop()
    while len(out[0])>1 and all(row[0]==0 for row in out): 
        for row in out: row.pop(0)
    while len(out[0])>1 and all(row[-1]==0 for row in out):
        for row in out: row.pop()
    return out
